# -*- coding: utf-8 -*-
"""Residentado Médico 2020 · Prueba B (especialidades mezcladas), preguntas 71-90"""
import lote08_base as B
L = []
def Q(n, tema, cat, c, f, nota=None, **kw): B.hacer(L, "PRUEBA_B", n, tema, cat, c, f, nota, **kw)

Q(71, "Hiperaldosteronismo primario: sitio de síntesis de la aldosterona", "Endocrinología suprarrenal",
  'La aldosterona se sintetiza en la zona glomerulosa de la corteza suprarrenal, que es la única capa que expresa aldosterona sintasa (CYP11B2) y que responde a la angiotensina II y al potasio. Un adenoma productor de aldosterona (síndrome de Conn) provoca retención de sodio con hipertensión, y pérdida urinaria de potasio e hidrogeniones. Esto explica el cuadro de la paciente: hipertensión de reciente inicio en una mujer joven, debilidad muscular con arreflexia por hipopotasemia de 2,3 mEq/l, alcalosis metabólica (pH 7,5, bicarbonato 38) con hipoventilación compensadora (pCO2 57) y una lesión nodular suprarrenal izquierda. La médula suprarrenal produce catecolaminas y su tumor, el feocromocitoma, causa crisis paroxísticas con cefalea, sudoración y palpitaciones, no hipopotasemia con alcalosis. La zona reticular sintetiza andrógenos suprarrenales, la zona fascicular produce cortisol (el hipercortisolismo da obesidad central, estrías y diabetes) y la cápsula es solo tejido de revestimiento que no sintetiza hormonas esteroideas. El tamizaje se hace con la relación aldosterona/renina, se confirma con una prueba de supresión, y la lateralización con cateterismo venoso suprarrenal define la adrenalectomía unilateral frente al tratamiento con antagonistas del receptor mineralocorticoide. La guía de la Endocrine Society de 2025, según su resumen, la considera una causa frecuente de hipertensión que sigue infradiagnosticada e infratratada. Perla: hipertensión con hipopotasemia espontánea o con incidentaloma suprarrenal obliga a descartar hiperaldosteronismo primario.',
  'Adler GK et al. J Clin Endocrinol Metab 2025;110:2453-2495 (guía de la Endocrine Society sobre aldosteronismo primario; solo resumen); Tseng CS et al. J Formos Med Assoc 2024;123(Suppl 2):S125-S134 (guía de tratamiento, Taiwan Society of Aldosteronism; solo resumen)',
  a="endocrinologia")

Q(72, "Endometritis puerperal", "Infección puerperal",
  'La endometritis puerperal es la infección polimicrobiana de la decidua y el miometrio, y es la complicación infecciosa más frecuente tras la cesárea. Los factores de riesgo del caso son la rotura prematura de membranas prolongada, la inducción fallida con trabajo de parto largo y la cesárea. La flora vaginal y genital (anaerobios, estreptococos, enterobacterias, micoplasmas) asciende y coloniza la cavidad uterina. El cuadro típico aparece entre el segundo y el quinto día posparto con fiebre, malestar, dolor uterino con subinvolución y loquios fétidos, exactamente lo descrito. La infección de herida operatoria presenta eritema, secreción y dolor localizados en la incisión, con el útero indoloro; la dehiscencia se manifiesta por salida de líquido o apertura de la herida; la retención de restos placentarios da sangrado persistente o hemorragia más que loquios fétidos con fiebre, aunque puede coexistir; la pielonefritis cursa con dolor lumbar, puñopercusión positiva y síntomas urinarios. La revisión de la corioamnionitis clínica a término publicada en 2024 recuerda que la rotura de membranas aumenta el riesgo de endometritis y que los micoplasmas genitales se aíslan en una proporción importante de los casos. El tratamiento es antibiótico endovenoso de amplio espectro con cobertura de anaerobios, clásicamente clindamicina más gentamicina, hasta 24 a 48 horas sin fiebre; si no hay respuesta se buscan absceso, hematoma o tromboflebitis pélvica séptica. Perla: fiebre posparto con útero doloroso y loquios fétidos es endometritis hasta demostrar lo contrario.',
  'Jung E et al. Am J Obstet Gynecol 2024;230(3S):S807-S840 (corioamnionitis clínica a término: texto completo en PMC); Williams Obstetricia 26.ª ed. (2022)',
  a="ginecologia")

Q(73, "Asfixia neonatal con encefalopatía hipóxico-isquémica", "Neonatología",
  'La asfixia perinatal es la alteración del intercambio gaseoso fetal que produce hipoxemia, hipercapnia y acidosis metabólica, y cuando se acompaña de disfunción neurológica se llama encefalopatía hipóxico-isquémica. El recién nacido del caso reúne las evidencias: sufrimiento fetal agudo, Apgar de 1 al minuto y solo 3 a los 5 minutos, acidosis grave con pH de cordón de 6,9, letargia, succión débil y convulsión generalizada precoz. Los criterios clásicos de acidosis son un pH de cordón menor de 7,0 o un déficit de base mayor de 12 a 16 mmol/l, y la revisión narrativa de 2023 de Korf recoge como criterios para hipotermia terapéutica una edad gestacional de 36 semanas o más, inicio dentro de las 6 horas, Apgar de 5 o menos a los 10 minutos, pH de cordón de 7,0 o menos y encefalopatía moderada a grave. La depresión neonatal es un diagnóstico más amplio y transitorio, sin acidosis grave ni convulsiones. La epilepsia primaria no se establece en el período neonatal inmediato; la meningitis neonatal exige factores infecciosos, y la parálisis cerebral es una secuela que se diagnostica meses después. El manejo comprende reanimación, control de glucosa y temperatura, hipotermia corporal total a 33,5 °C durante 72 horas y tratamiento de las convulsiones con fenobarbital como primera línea, según el consenso de la ILAE de 2023. La atención inmediata sigue la NTS 214-MINSA/DGIESP-2024. Perla: la hipotermia terapéutica solo es eficaz si se inicia en las primeras 6 horas de vida.',
  'Korf JM et al. Transl Pediatr 2023;12:1552-1571 (texto completo en PMC); Pressler RM et al. Epilepsia 2023;64:2550-2570 (guía ILAE de convulsiones neonatales; solo resumen); NTS 214-MINSA/DGIESP-2024 (atención integral del neonato); ' + B.NEL,
  a="pediatria")

Q(74, "Dermatomiositis", "Enfermedades del tejido conectivo",
  'La dermatomiositis es una miopatía inflamatoria autoinmune mediada por complemento y por interferón tipo I, que lesiona los capilares endomisiales y la piel. Se manifiesta como debilidad muscular proximal, simétrica y progresiva, de cinturas escapular y pelviana, y lesiones cutáneas características: el exantema heliotropo (eritema violáceo periorbitario con edema palpebral) y las pápulas o placas eritematosas sobre las articulaciones de los dedos, llamadas pápulas de Gottron. Estas lesiones cutáneas pueden preceder a la debilidad. El eritema polimorfo da lesiones en diana tras infecciones o fármacos. La esclerodermia produce engrosamiento cutáneo, Raynaud y esclerodactilia. El lupus presenta eritema malar fotosensible, artritis y compromiso renal, y puede dar miositis leve pero no esta combinación. La artritis reumatoide es una poliartritis simétrica de pequeñas articulaciones. Se confirma con elevación de creatina cinasa y aldolasa, electromiografía, resonancia o biopsia muscular y autoanticuerpos específicos (anti-Mi-2, anti-MDA5, anti-TIF1γ, anti-NXP2), y se aplican los criterios de clasificación EULAR/ACR de 2017, cuyo desempeño en adultos y niños se ha revisado en 2024. Se debe buscar neoplasia asociada, sobre todo en adultos con anti-TIF1γ. El tratamiento inicial es glucocorticoide más inmunosupresor ahorrador (metotrexato, azatioprina), con inmunoglobulina endovenosa en casos graves. Perla: una dermatomiositis del adulto obliga a descartar una neoplasia oculta.',
  'Didona D et al. Ital J Dermatol Venerol 2023;158:84-98 (solo resumen); Saygin D et al. Clin Exp Rheumatol 2024;42:403-412 (criterios EULAR/ACR 2017; solo resumen); Kutwin M et al. J Clin Med 2026;15(8) (manifestaciones cutáneas; texto completo en PMC)',
  a="reumatologia")

Q(75, "Diagnóstico de asma: prueba de respuesta al broncodilatador", "Neumología",
  'El asma es una enfermedad inflamatoria crónica de la vía aérea con obstrucción variable al flujo aéreo. La paciente tiene atopia (rinitis alérgica), tos y sibilancias nocturnas, y una espirometría con relación VEF1/CVF de 60 %, que demuestra obstrucción. Como el asma se caracteriza por una limitación reversible, el siguiente paso para confirmar el diagnóstico es la prueba de respuesta al broncodilatador. La guía GINA, resumida en 2023 en NPJ Prim Care Respir Med, establece que en adultos y adolescentes un aumento del VEF1 mayor de 12 % y mayor de 200 ml tras 10 a 15 minutos de un agonista beta-2 de acción corta, con mayor confianza si supera 15 % y 400 ml, apoya el diagnóstico, y que si no se documenta al inicio la prueba puede repetirse en otras visitas. La tomografía y la radiografía de tórax sirven para descartar otras patologías, pero no confirman asma. Una prueba con vasodilatadores o con antihistamínicos no tiene ningún papel diagnóstico. Si la espirometría fuera normal, se recurre a la variabilidad del flujo espiratorio máximo o a la prueba de provocación bronquial con metacolina. Una vez confirmado, el tratamiento actual de elección es corticoide inhalado con formoterol según necesidad y de mantenimiento, evitando el SABA solo. Perla: una espirometría normal no excluye asma y una obstrucción persistente plantea la superposición con EPOC.',
  'Levy ML et al. NPJ Prim Care Respir Med 2023;33:7 (recomendaciones clave de GINA 2022 para atención primaria; texto completo en PMC); Kasper DL (ed). Harrison Principios de Medicina Interna 21.ª ed. (2022)',
  a="neumologia")

Q(76, "Púrpura trombocitopénica inmune (PTI) en el niño", "Hematología pediátrica",
  'La púrpura trombocitopénica inmune pediátrica es un trastorno autoinmune adquirido en el que autoanticuerpos contra las glicoproteínas plaquetarias destruyen las plaquetas y alteran la megacariopoyesis. Aparece típicamente en un niño de 2 a 6 años, previamente sano, con una infección viral o una vacuna 1 a 4 semanas antes, y con petequias y epistaxis súbitas. El hemograma muestra trombocitopenia aislada (8000 por mm3) con hemoglobina y leucocitos normales, sin hepatoesplenomegalia. La leucemia linfoblástica aguda se acompaña de otras citopenias, blastos, adenopatías o hepatoesplenomegalia; la aplasia medular produce pancitopenia; la hemofilia B causa hemartrosis y tiene plaquetas normales; y la púrpura de Henoch-Schönlein da púrpura palpable en glúteos y piernas, dolor abdominal y artritis con plaquetas normales. El diagnóstico es de exclusión. En la actualización anual de 2024 (año 2022) de las guías de la ASH de 2019, para niños con PTI recién diagnosticada se mantienen como opciones la observación o la inmunoglobulina intravenosa, y la prednisona o dexametasona de corta duración cuando se requiere corticoide; no se recomienda la observación sola si hay sangrado grave. La mayoría remite espontáneamente en seis meses. Perla: la punción de médula ósea no es obligatoria si el cuadro clínico y el hemograma son típicos.',
  'Neunert CE et al. Blood Adv 2024;8:3578-3582 (revisión 2022 de las guías ASH 2019; texto completo en PMC); Mahamad S et al. Res Pract Thromb Haemost 2023;7:100097 (cumbre sobre PTI; texto completo en PMC); ' + B.NEL,
  a="hematologia")

Q(77, "Fascitis necrosante perineal (gangrena de Fournier)", "Infecciones de piel y partes blandas",
  'La gangrena de Fournier es una fascitis necrosante del periné y los genitales, de origen polimicrobiano (aerobios y anaerobios), cuyo punto de partida suele ser un foco anorrectal, urogenital o cutáneo. La diabetes mellitus, el alcoholismo y la inmunosupresión son los principales factores de riesgo, como en este varón. La trombosis de los vasos subcutáneos produce isquemia, necrosis y progresión rápida con toxicidad sistémica, por lo que la mortalidad es de 20 a 30 %. El diagnóstico es clínico: dolor desproporcionado, crepitación, ampollas, áreas cutáneas necróticas, fiebre y compromiso del estado general. El tratamiento inicial es el desbridamiento quirúrgico amplio y urgente de todo el tejido necrótico, con reexploraciones programadas cada 24 a 48 horas. La revisión narrativa de 2023 de Desai confirma que el diagnóstico oportuno, el soporte médico y el desbridamiento quirúrgico completo siguen siendo las bases del tratamiento. Los antibióticos de amplio espectro por vía endovenosa (carbapenem o piperacilina-tazobactam, más vancomicina o linezolid y clindamicina) son imprescindibles, pero no reemplazan la cirugía. Los antiinflamatorios y las cremas son inútiles. La cámara hiperbárica es adyuvante: el metaanálisis de 2023 de Huang observó menor mortalidad, pero con evidencia retrospectiva débil y sin disponibilidad universal. Perla: el control del foco es lo primero, y retrasar la cirugía aumenta la mortalidad.',
  'Desai R et al. Urologia 2023;90:201-208 (gangrena de Fournier; solo resumen); Huang C et al. World J Emerg Surg 2023;18:23 (oxígeno hiperbárico en infecciones necrosantes; texto completo en PMC); Sabiston Tratado de Cirugía 22.ª ed. (Elsevier, 2025)',
  a="cirugia")

Q(78, "Envenenamiento por Latrodectus (viuda negra)", "Toxicología",
  'La araña con una marca en reloj de arena en la parte inferior del abdomen es Latrodectus (viuda negra). Su veneno contiene alfa-latrotoxina, que abre canales de calcio presinápticos y provoca liberación masiva de acetilcolina, noradrenalina y otros neurotransmisores. Produce el latrodectismo: dolor intenso en el sitio de la mordedura que se irradia, espasmos y rigidez musculares generalizados (abdomen en tabla), sudoración, hipersalivación, taquicardia y, con frecuencia, hipertensión; en casos graves hay compromiso cardiovascular. La revisión sistemática de 2024 de Khakh sobre complicaciones cardiovasculares reunió 25 pacientes, con hipertensión en 68 % y elevación de troponina en 64 %, y solo 6 recibieron antiveneno. En un cuadro grave con dolor refractario, compromiso hemodinámico y espasmos difusos, el tratamiento inicial de elección es el antídoto específico (antiveneno antilatrodectus) por vía endovenosa, junto con analgesia opioide y benzodiacepinas para el espasmo. Los antibióticos (ampicilina, vancomicina) no tienen indicación, porque el cuadro es neurotóxico y no infeccioso. La dopamina y la albúmina solo se justificarían como soporte hemodinámico secundario, no como tratamiento del veneno. Se vigila la presión arterial, el electrocardiograma y los marcadores cardíacos. Perla: el gluconato de calcio ya no se recomienda como tratamiento de rutina por su eficacia limitada.',
  'Khakh P et al. Cureus 2024;16:e73342 (viuda negra y complicaciones cardiovasculares; texto completo en PMC); Warpinski GP et al. Emerg Med Clin North Am 2022;40:313-326 (síndromes de envenenamiento de Norteamérica; solo título); Goldfrank Toxicologic Emergencies 11.ª ed. (2019)',
  a="infectologia",
  nota="La clave oficial (antídoto específico) se mantiene. La hipotensión del enunciado es poco típica del latrodectismo, que cursa con hipertensión; la elección de antiveneno es aun así la respuesta específica.")

Q(79, "Estudio no invasivo para coledocolitiasis", "Vía biliar",
  'La coledocolitiasis es la presencia de cálculos en el colédoco, ya sea primaria o secundaria al paso de cálculos vesiculares. Se sospecha ante colestasis (bilirrubina y fosfatasa alcalina elevadas), colédoco dilatado en la ecografía o antecedente de ictericia o pancreatitis. La guía ASGE de 2019 estratifica el riesgo y reserva la CPRE para los pacientes de alto riesgo, mientras que en riesgo intermedio se recomienda confirmar con un estudio menos invasivo. La colangiorresonancia magnética (CPRM) es la prueba no invasiva de elección porque no usa radiación ni contraste biliar, su sensibilidad y especificidad son altas (cercanas al 90 %), y evita el riesgo de pancreatitis de la CPRE. La ecografía es el primer estudio, pero ve poco el colédoco distal. La radiografía de abdomen casi nunca muestra cálculos biliares. La ecoendoscopía tiene rendimiento equivalente a la CPRM, pero requiere endoscopia con sedación, por lo que se considera mínimamente invasiva. La CPRE es el procedimiento terapéutico y la más invasiva, con riesgo de pancreatitis, hemorragia y perforación. La evaluación de 2023 de las guías de coledocolitiasis incluyó la CPRM y la ecoendoscopía como pruebas de imagen complementarias recomendadas por las guías. En el Perú se aplica la GPC N.º 11 de EsSalud-IETSI. Perla: ante riesgo intermedio, CPRM o ecoendoscopía antes de la CPRE.',
  'Zhu SY et al. Surg Laparosc Endosc Percutan Tech 2023;33:673-681 (evaluación sistemática de guías de coledocolitiasis; texto completo en PMC); ASGE Standards of Practice Committee. Gastrointest Endosc 2019;89:1075-1105.e15 (solo resumen); GPC N.º 11 EsSalud-IETSI colelitiasis, colecistitis y coledocolitiasis (2018); Sabiston Tratado de Cirugía 22.ª ed. (Elsevier, 2025)',
  a="cirugia")

Q(80, "Microtoma de sangre fetal: pH 7,20-7,25", "Monitoreo fetal intraparto",
  'La microtoma de sangre del cuero cabelludo fetal se usa como prueba complementaria cuando el registro cardiotocográfico es patológico, para distinguir entre hipoxia real y un patrón desacelerativo sin acidosis. Las categorías clásicas son: pH mayor de 7,25 normal, 7,20 a 7,25 prepatológico o preacidosis, y menor o igual a 7,20 acidosis, que obliga a terminar el parto de inmediato. La revisión analítica y clínica de 2024 de Spronk resume esos umbrales y señala que en la preacidosis se aconseja repetir la prueba pasados 30 minutos, que es la ventana en que la misma cifra puede evolucionar a acidosis o normalizarse. Por eso el valor de 7,22 de esta gestante, en trabajo de parto activo con 6 cm de dilatación, exige repetir la microtoma en un intervalo corto (15 a 30 minutos) mientras se aplican medidas de reanimación intrauterina: decúbito lateral, hidratación, suspensión de oxitocina y oxigenoterapia solo si se indica. No se justifica repetir por «error de toma» ni dejar la evolución natural, porque el valor no es normal. La cesárea urgente corresponde a pH de 7,20 o menos o a una lactacidemia fetal elevada, y no se espera 1 a 2 horas. Un estudio de 2023 de Berge mostró más resultados neonatales adversos cuando pasan más de 20 minutos entre una lactacidemia alta y el parto. Perla: pH de 7,20 a 7,25 se repite en menos de una hora; menos de 7,20 se interrumpe el embarazo.',
  'Spronk N et al. Pract Lab Med 2024;39:e00375 (lactato POCT en muestras de sangre fetal; texto completo en PMC); Berge MB et al. Acta Obstet Gynecol Scand 2023;102:1106-1114 (lactato fetal y tiempo hasta el parto; texto completo en PMC); Williams Obstetricia 26.ª ed. (2022)',
  a="ginecologia",
  nota="La clave oficial (repetir microtoma) se mantiene. Los textos consultados indican repetir tras unos 30 minutos; el intervalo de 15 a 20 minutos de la opción B es el criterio del examen y es coherente con repetir en un lapso corto.")

Q(81, "Sepsis neonatal precoz", "Neonatología",
  'La sepsis neonatal precoz es la infección bacteriana invasiva que se manifiesta dentro de las primeras 72 horas de vida, adquirida por vía vertical (ascendente por la rotura de membranas, o por paso por el canal del parto). Los agentes principales son el estreptococo del grupo B y Escherichia coli. Los factores de riesgo del caso son claros: fiebre materna, rotura de membranas de más de 18 horas y líquido amniótico fétido, que sugieren corioamnionitis. Las manifestaciones a las 13 horas de vida (irritabilidad, letargo, inestabilidad térmica, ictericia precoz y hepatomegalia) son inespecíficas, pero típicas del cuadro. La sepsis tardía y la nosocomial aparecen después de las 72 horas, con colonización posnatal o hospitalaria. La candidiasis neonatal se observa en prematuros con catéteres. La sífilis congénita temprana puede dar hepatoesplenomegalia, rinitis y lesiones cutáneas, pero requiere antecedente materno de sífilis. La revisión suiza de 2024 de Stocker indica tomar hemocultivos antes del antibiótico y que, como tratamiento empírico, se emplee amoxicilina más un aminoglucósido, con suspensión a las 24 a 36 horas si el hemocultivo es negativo y el cuadro clínico lo permite. En neonatos con signos de shock séptico, el antibiótico debe darse sin demora. En el Perú se aplica la NTS 214-MINSA/DGIESP-2024 para la atención del neonato. Perla: ante factores de riesgo y signos clínicos, se toman cultivos y se inicia antibiótico sin esperar resultados.',
  'Stocker M et al. Eur J Pediatr 2024;183:5517-5529 (neonatos en riesgo de sepsis precoz; texto completo en PMC); NTS 214-MINSA/DGIESP-2024 (atención integral del neonato); ' + B.NEL,
  a="pediatria")

Q(82, "Interleucina 2 y células T", "Inmunología",
  'La interleucina 2 (IL-2) es una citocina producida principalmente por los linfocitos T CD4 colaboradores tras el reconocimiento del antígeno y la coestimulación CD28. Actúa en forma autocrina y paracrina sobre su receptor, que en su forma de alta afinidad es trimérico (cadenas alfa o CD25, beta y gamma común). Su señal activa la vía JAK1/JAK3-STAT5, la vía PI3K-AKT-mTOR y la vía MAPK, y promueve la supervivencia, la proliferación (expansión clonal) y la diferenciación de las células T activadas por antígeno hacia efectoras y de memoria, además de estimular a las células NK. La revisión de 2023 de Lykhopiy recuerda que la IL-2 tiene efectos pleiotrópicos de supervivencia, expansión y estabilidad de linaje y que mantiene a las células T reguladoras, que dependen de la IL-2 externa. La IL-4 dirige la diferenciación Th2 y el cambio de clase a IgE; la IL-1 es una citocina proinflamatoria que induce fiebre y proteínas de fase aguda; la IL-3 es un factor de crecimiento hematopoyético multilinaje, y la IL-5 estimula la maduración del eosinófilo y la producción de IgA. Clínicamente, la IL-2 recombinante (aldesleukina) se ha utilizado en melanoma y carcinoma renal metastásico, y la IL-2 en dosis bajas se investiga para expandir células reguladoras en enfermedades autoinmunes. Perla: IL-2 = factor de crecimiento de la célula T; IL-4 = Th2 e IgE; IL-5 = eosinófilo.',
  'Lykhopiy V et al. Genes Immun 2023;24:248-262 (inmunoterapia con IL-2 y células T reguladoras; texto completo en PMC); Leonard WJ et al. Nat Rev Drug Discov 2023;22:827-854 (modulación terapéutica de citocinas; solo resumen)',
  a="ciencias_basicas")

Q(83, "Hepatitis B aguda: interpretación serológica", "Hepatitis virales",
  'El virus de la hepatitis B (VHB) es un virus ADN hepatotropo que se transmite por vía parenteral, sexual y perinatal. La infección aguda en el adulto se manifiesta con malestar, ictericia y elevación de transaminasas, que en la fase aguda puede superar las 1000 a 2000 UI/l. La serología del caso, con HBsAg positivo y anti-HBc IgM positivo, define infección aguda por VHB, porque el anti-HBc IgM aparece en la hepatitis aguda y es el marcador de infección reciente. El anti-VHA IgM negativo descarta hepatitis A aguda, y el anti-VHC negativo descarta hepatitis C. La infección crónica se define por HBsAg persistente por más de 6 meses, con anti-HBc total positivo a expensas de IgG y anti-HBc IgM negativo. La sobreinfección por virus delta requiere anticuerpos anti-VHD y suele producir una descompensación en un portador crónico. La hepatitis tóxica se asocia con exposición a fármacos o sustancias, con serología viral negativa. Las nuevas guías EASL de 2025 sobre infección por VHB y las recomendaciones actualizadas de la OMS de 2024 insisten en el diagnóstico oportuno, la vacunación y el tamizaje (según sus resúmenes). La mayoría de los adultos inmunocompetentes con hepatitis B aguda se recupera espontáneamente y solo requiere soporte, con antivirales si hay insuficiencia hepática aguda grave o coagulopatía. Perla: HBsAg con anti-HBc IgM es hepatitis B aguda; con anti-HBc IgM negativo, infección crónica.',
  'European Association for the Study of the Liver. J Hepatol 2025;83:502-583 (guía EASL del VHB; solo resumen); Wong GL et al. J Hepatol 2025;82:918-925 (guías OMS 2024 de hepatitis B crónica; solo resumen); Harrison Principios de Medicina Interna 22.ª ed. (2025)',
  a="gastroenterologia")

Q(84, "Niveles de prevención de Leavell y Clark: la gota gruesa", "Epidemiología y salud pública",
  'El modelo de Leavell y Clark describe los niveles de prevención según la historia natural de la enfermedad. La prevención primaria actúa en el período prepatogénico para evitar que aparezca la enfermedad, mediante promoción de la salud y protección específica (vacunas, control vectorial, mosquiteros). La prevención secundaria actúa cuando la enfermedad ya existe, pero aún no se manifiesta o está en etapa temprana, con diagnóstico precoz y tratamiento oportuno para frenar su progresión, incluye el tamizaje y la búsqueda activa de casos. Eso es la gota gruesa para detectar malaria: es un examen diagnóstico que permite identificar casos y tratarlos a tiempo y cortar la transmisión. La prevención terciaria busca limitar la discapacidad y rehabilitar al paciente con secuelas, y la prevención primordial interviene sobre los determinantes sociales y ambientales para evitar la aparición de factores de riesgo. La prevención cuaternaria protege al paciente de intervenciones médicas innecesarias o excesivas. Una revisión de 2023 sobre los niveles de prevención los describe en estos mismos términos. El diagnóstico y tratamiento de la malaria en el Perú se rigen por la NTS 233-MINSA/DGIESP-2025, que mantiene la microscopía de gota gruesa como método de referencia junto con las pruebas rápidas. Perla: diagnóstico precoz, tamizaje y tratamiento oportuno equivalen a prevención secundaria.',
  'AbdulRaheem Y et al. J Prim Care Community Health 2023;14:21501319231186500 (niveles de prevención; texto completo en PMC); NTS 233-MINSA/DGIESP-2025 (malaria; RM 609-2025/MINSA); Gordis Epidemiología 6.ª ed. (2019)',
  a="salud_publica")

Q(85, "Sobredosis de opioides: hipoventilación pura", "Fisiología respiratoria y toxicología",
  'Los opioides como la heroína actúan sobre los receptores mu del tronco encefálico, en la región del núcleo parabraquial y del complejo preBötzinger, y deprimen el centro respiratorio, de modo que reducen la frecuencia respiratoria y la sensibilidad a la hipercapnia. Una revisión neurobiológica de 2023 describe la convergencia de los receptores mu en estos circuitos de sueño, analgesia y depresión respiratoria. El resultado es hipoventilación alveolar con pulmones sanos: la PaCO2 sube de forma directamente proporcional a la caída de la ventilación alveolar y la PaO2 desciende, pero el gradiente alveoloarterial de oxígeno (A-a) es normal, porque el defecto es de bomba ventilatoria y no del intercambio gaseoso a través de la membrana alveolocapilar. Por ello la opción correcta combina CO2 elevado con gradiente A-a normal. Un CO2 normal es incompatible con hipoventilación significativa; un gradiente elevado indicaría enfermedad pulmonar intrínseca (alteración V/Q, shunt, difusión, edema pulmonar), que puede aparecer después de la sobredosis por aspiración o edema pulmonar no cardiogénico, pero no en este paciente sin enfermedad pulmonar. La PaCO2 baja con gradiente elevado ocurre en la embolia pulmonar. El tratamiento es naloxona, de acción corta, con ventilación asistida, vigilando la renarcotización. Perla: hipoxemia con gradiente A-a normal significa hipoventilación; con gradiente elevado, enfermedad pulmonar.',
  'Lynch N et al. Front Neurosci 2023;17:1134842 (receptores mu y depresión respiratoria; texto completo en PMC); Khanna AK et al. J Clin Anesth 2024;94:111374 (oximetría y capnografía continuas en insuficiencia respiratoria posoperatoria; solo resumen); West Fisiología Respiratoria 11.ª ed. (2021)',
  a="neumologia")

Q(86, "Condilomas acuminados y tipos de VPH", "Infecciones de transmisión sexual",
  'Las lesiones verrucosas en racimo del área genital externa y el periné corresponden a condilomas acuminados, causados en más del 90 % de los casos por los tipos de bajo riesgo oncogénico 6 y 11 del virus del papiloma humano. Estos tipos infectan el epitelio cutaneomucoso y producen lesiones exofíticas benignas; los tipos 16 y 18 son los de alto riesgo, responsables de cerca del 70 % de los cánceres de cuello uterino, y los tipos 31, 33, 35, 45, 51 y 52 son también oncogénicos y se asocian con lesiones intraepiteliales, no con verrugas genitales. La revisión de 2023 de Plotzker precisa que los tipos de bajo riesgo causan verrugas anogenitales, que se manejan con terapias aplicadas por el paciente o el proveedor, y que los de alto riesgo causan cánceres anogenitales. En la gestante, las verrugas pueden crecer y hacerse friables por los cambios hormonales e inmunitarios; no se utilizan podofilina, podofilotoxina ni imiquimod durante el embarazo, y se prefieren crioterapia, ácido tricloroacético o escisión. La cesárea no se indica solo por condilomas, salvo obstrucción del canal del parto o riesgo hemorrágico. El recién nacido puede presentar papilomatosis laríngea, poco frecuente. La vacuna nonavalente cubre los tipos 6, 11, 16, 18, 31, 33, 45, 52 y 58. El manejo de las ITS en el Perú se rige por la NTS 240-MINSA/DGIESP-2026. Perla: verrugas genitales = VPH 6 y 11; cáncer cervical = VPH 16 y 18.',
  'Plotzker RE et al. Infect Dis Clin North Am 2023;37:289-310 (VPH de transmisión sexual; solo resumen); NTS 240-MINSA/DGIESP-2026 (ITS; RM 035-2026-MINSA); Workowski KA et al. MMWR Recomm Rep 2021;70(4):1-187 (guía CDC de ITS, complemento)',
  a="infectologia")

Q(87, "Antihipertensivo de elección en diabetes con albuminuria", "Nefropatía diabética e hipertensión",
  'La paciente con diabetes de 10 años, hipertensión (155/95 mmHg) y albuminuria intensa tiene nefropatía diabética incipiente. La relación albúmina/creatinina muy elevada indica albuminuria grave (el límite de albuminuria es 30 mg/g, equivalente a 3 mg/mmol), con creatinina aún normal. En estos pacientes la primera elección son los fármacos que bloquean el sistema renina-angiotensina-aldosterona, es decir, los inhibidores de la enzima convertidora de angiotensina (IECA) o los antagonistas de los receptores de angiotensina II (ARA II): reducen la presión intraglomerular por dilatación de la arteriola eferente, disminuyen la proteinuria y retrasan la progresión de la enfermedad renal. Entre las opciones, el bloqueador del receptor de angiotensina (ARA II) es el único de este grupo. Los calcioantagonistas y los diuréticos tiazídicos son eficaces para bajar la presión, pero no tienen el beneficio renal específico y se añaden como segundo o tercer fármaco; los betabloqueadores no son de primera línea; y el antagonista de aldosterona (espironolactona, finerenona) es un complemento en la albuminuria persistente. Se debe controlar creatinina y potasio a las 1 a 2 semanas de empezar y no combinar IECA con ARA II. Las guías KDIGO 2024 de enfermedad renal crónica y los Standards of Care de la ADA 2025 (capítulo de enfermedad renal) abordan este manejo (según sus resúmenes). Perla: diabético hipertenso con albuminuria, IECA o ARA II; si hay embarazo posible, evitarlos.',
  'American Diabetes Association Professional Practice Committee. Diabetes Care 2025;48(Suppl 1):S239-S251 (capítulo 11, Standards of Care; solo resumen); KDIGO CKD Work Group. Kidney Int 2024;105(4S):S117-S314 (solo resumen); Harrison Principios de Medicina Interna 22.ª ed. (2025)',
  a="nefrologia",
  nota="Se mantiene la clave oficial. La unidad del enunciado (1000 mg/mmol) es inusual; con cualquier valor por encima de 3 mg/mmol (30 mg/g) la conducta es la misma.")

Q(88, "Hormona imprescindible para la ovulación", "Fisiología del ciclo ovárico",
  'La ovulación es la ruptura del folículo dominante con liberación del ovocito. Su desencadenante es el pico preovulatorio de hormona luteinizante (LH), que se produce cuando el estradiol, secretado en cantidad y duración suficientes por el folículo dominante (cerca de 200 pg/ml durante 48 horas), cambia su efecto sobre el eje hipotálamo-hipofisario de retroalimentación negativa a positiva. El pico de LH induce la reanudación de la meiosis del ovocito, la expansión del cúmulo, la luteinización de las células de la granulosa, la síntesis de enzimas proteolíticas y prostaglandinas que degradan la pared folicular, y la ruptura, unas 36 horas después. El estudio de 2023 de Lund muestra incluso que el pico de LH promueve la angiogénesis ovárica a través de su receptor en células endoteliales, y la revisión de fisiología de 2023 indica que la ovulación está regulada por los niveles fluctuantes de FSH y LH. El crecimiento folicular terminal depende de la LH sobre la teca, que produce los andrógenos que la granulosa convierte en estradiol por acción de la FSH (modelo de dos células, dos gonadotropinas). La estrona es un estrógeno débil, la activina y la folistatina son moduladores locales de la FSH, y la progesterona es producto del cuerpo lúteo posterior a la ovulación, aunque su aumento inicial contribuye al pico de LH. Perla: sin pico de LH no hay ovulación, y por eso se usa hCG o agonistas de GnRH para desencadenarla en reproducción asistida.',
  'Holesh JE et al. StatPearls (Physiology, Ovulation) 2023 (solo resumen); Lund M et al. Biol Reprod 2023;108:258-268 (receptor de LH y angiogénesis ovárica; solo resumen); Williams Ginecología 4.ª ed. (2020)',
  a="ginecologia")

Q(89, "Persistencia del uraco", "Neonatología y urología pediátrica",
  'El uraco es el remanente tubular de la alantoides que une la cúpula vesical con el ombligo durante la vida fetal y que normalmente se oblitera hacia el quinto mes para formar el ligamento umbilical medio. Su falta de involución produce anomalías: uraco permeable (lumen completo entre vejiga y ombligo), seno umbilical-uracal, quiste del uraco y divertículo vesicouracal. La revisión de 2023 de Ghattas describe estos subtipos y precisa que el uraco permeable mantiene una luz completa entre la vejiga y el ombligo. El cuadro del recién nacido es característico: salida persistente de líquido claro, transparente y amarillento por el ombligo, que corresponde a orina, de pH ácido, sin otras alteraciones. Se confirma por ecografía y fistulografía, y la creatinina del líquido es similar a la de la orina. La persistencia del conducto onfalomesentérico (vitelino) elimina contenido intestinal, mucoso o fecaloide, con pH variable. La onfalitis cursa con eritema, edema y secreción purulenta periumbilical; la gastrosquisis es un defecto de pared abdominal paraumbilical con eventración intestinal, y el impétigo ampolloso causa ampollas cutáneas. La revisión citada señala que la conducta ha sido históricamente motivo de debate entre el manejo conservador inicial y el quirúrgico, y que la evidencia respalda un manejo inicial conservador en los pacientes pediátricos, con observación y ecografía, y cirugía si hay infección persistente. Perla: orina por el ombligo, uraco; contenido intestinal, conducto onfalomesentérico.',
  'Ghattas YS et al. Front Urol 2023;3:1159439 (anomalías del uraco en pediatría; texto completo en PMC); ' + B.NEL,
  a="pediatria")

Q(90, "Alexia sin agrafia por infarto de la cerebral posterior", "Neurología vascular",
  'El paciente presenta hemianopsia homónima derecha e incapacidad para leer con escritura conservada, lo que se denomina alexia sin agrafia (síndrome de Déjerine). Se debe a una lesión de la corteza visual izquierda (occipital) y del esplenio del cuerpo calloso o de las fibras occipitales izquierdas: la hemianopsia derecha obliga a que la información visual llegue solo al hemisferio derecho, y la interrupción en el esplenio impide que esa información llegue al área del lenguaje del hemisferio izquierdo. El centro de la escritura queda intacto. Ambos hallazgos dependen del territorio de la arteria cerebral posterior izquierda. La revisión de 2023 de Robotham sobre ictus de la arteria cerebral posterior recuerda que estos pacientes presentan hemianopsia y déficits visuales de alto nivel, y que la alexia pura se asocia con lesiones occipitotemporales izquierdas. El antecedente de fibrilación auricular y el inicio brusco sugieren un infarto cardioembólico. La arteria cerebral media izquierda produciría afasia, hemiparesia y déficit sensitivo contralateral; la cerebral anterior, debilidad crural y abulia; la coroidea anterior, hemiplejía, hemihipoestesia y hemianopsia; y una lesión de la cerebral media derecha daría negligencia. El manejo agudo es la trombólisis intravenosa dentro de la ventana, o trombectomía si hay oclusión de gran vaso, y luego la anticoagulación por la fibrilación auricular. Perla: alexia sin agrafia más hemianopsia derecha, infarto de la cerebral posterior izquierda.',
  'Robotham RJ et al. Brain Commun 2023;5:fcad050 (déficits visuales de alto nivel en el ictus de la arteria cerebral posterior; texto completo en PMC); Harrison Principios de Medicina Interna 22.ª ed. (2025)',
  a="neurologia")
